            float fromD[3],toD[3]; int j=(i<n-1)?i+1:i, j0=(i<n-1)?i:i-1;
            for(int k=0;k<3;k++){ fromD[k]=a[j][k]-a[j0][k]; toD[k]=sp[who][c][j][k]-sp[who][c][j0][k]; }
