        if(par>=0){ char lp[96]; const char*s1=packStr(&P,P.nodes[par].name);
            for(k=0;k<95&&s1[k];k++) lp[k]=(char)((s1[k]>='A'&&s1[k]<='Z')?s1[k]+32:s1[k]); lp[k]=0;
            parMatch=CHNAME(lp); }
