            for(;k2<31&&nm2[k2];k2++){ char c2=nm2[k2]; lo2[k2]=(c2>='A'&&c2<='Z')?c2+32:c2; } lo2[k2]=0;
            float d2=P.nodes[i].t[0]*P.nodes[i].t[0]+P.nodes[i].t[1]*P.nodes[i].t[1]+P.nodes[i].t[2]*P.nodes[i].t[2];
