static void gmBanner(const char*s,float t){
    if(strcmp(GM.msg,s)) sfxPlay("banner",0.35f,NULL,0);   /* a NEW banner pings; a repeat does not */
    snprintf(GM.msg,sizeof GM.msg,"%s",s); GM.msgT=t; }
/* ---- neon overlay lines: the game layer's own geometry (rings, markers, cursors,
 * platforms, hit arcs). One dynamic GL_LINES batch, flushed once per frame. ---- */
#define GMV_MAX 4096
static float gmV[GMV_MAX*6]; static int gmN=0;
static void gmLine(float x1,float y1,float z1,float x2,float y2,float z2,float r,float g,float b){
    if(gmN+2>GMV_MAX) return;
    float*v=gmV+gmN*6; v[0]=x1;v[1]=y1;v[2]=z1;v[3]=r;v[4]=g;v[5]=b;
    v+=6; v[0]=x2;v[1]=y2;v[2]=z2;v[3]=r;v[4]=g;v[5]=b; gmN+=2; }
static void gmRing(float cx,float cz,float rad,float y,float r,float g,float b,int segs){
    if(segs<8)segs=8; if(segs>128)segs=128;
    for(int i=0;i<segs;i++){ float a0=(float)i/segs*6.28318f, a1=(float)(i+1)/segs*6.28318f;
        gmLine(cx+sinf(a0)*rad,y,cz+cosf(a0)*rad, cx+sinf(a1)*rad,y,cz+cosf(a1)*rad, r,g,b); } }
static void gmMarker(float x,float z,float h,float r,float g,float b){
    gmRing(x,z,1.6f,0.12f,r,g,b,24);
    gmLine(x,0.1f,z,x,h,z,r,g,b);
    gmLine(x-0.6f,h*0.8f,z,x,h,z,r,g,b); gmLine(x,h,z,x+0.0f,h*0.8f,z+0.6f,r,g,b); }
static void gmBurst(float x,float y,float z,float r,float g,float b,int n,float rad){
    for(int i=0;i<n;i++){ float a=(float)i/n*6.28318f, e=((i*37)%100)/100.f*2.4f;
        gmLine(x,y,z, x+sinf(a)*rad*cosf(e),y+sinf(e)*rad,z+cosf(a)*rad*cosf(e), r,g,b); } }
/* the platformer course: {x0, x1, topY} on the fixed lane; a staircase of neon ledges
 * ending at the goal gate. Orbs sit above some of them (bitmask GM.count = collected). */
static const float GMPLAT[][3]={
    {-6,-2,1.2f},{0,4,2.2f},{6,9,3.2f},{11,14,2.4f},{16,20,3.6f},{22,25,4.8f},
    {27,30,3.4f},{32,36,4.6f},{38,41,5.8f},{43,47,4.2f},{49,53,5.4f},{55,60,6.5f}};
#define GMPLAT_N 12
static const float GMORB[][2]={{-4,2.4f},{2,3.4f},{7.5f,4.4f},{18,4.8f},{23.5f,6.0f},{34,5.8f},{39.5f,7.0f},{51,6.6f}};
#define GMORB_N 8
#define GMPLAT_GOALX 63.f
/* ================= DATA-DRIVEN DOORS (09-11) ==========================================
 * The audit: "No course, quest or dialogue file format. The platformer, ARPG and narrative
 * RPG designs all assume one." The course above and the elder's errand below were C tables
 * and a switch. They are FILES now -- data/plat_course.txt and data/nrpg_quest.txt -- read
 * at boot into these arrays; the tables stay as the fallback and the fallback is loud.
 * REVA_PLAT_COURSE / REVA_NRPG_QUEST point a door at another file (the A/B, and a level
 * pack later). Edit, relaunch: no rebuild. */
#define PLAT_MAX 64
#define ORB_MAX 32
static float g_plat[PLAT_MAX][3]; static int g_nPlat=0;
static float g_orb[ORB_MAX][2];   static int g_nOrb=0;
static float g_platGoal=GMPLAT_GOALX;
static void platLoad(void){
    const char*path=getenv("REVA_PLAT_COURSE"); if(!path||!path[0]) path="data/plat_course.txt";
    g_nPlat=0; g_nOrb=0; g_platGoal=GMPLAT_GOALX;
    FILE*f=fopen(path,"r");
    if(f){ char ln[256];
        while(fgets(ln,sizeof ln,f)){ float a,b,c;
            if(ln[0]=='#'||ln[0]=='\n'||ln[0]=='\r') continue;
            if(sscanf(ln,"ledge %f %f %f",&a,&b,&c)==3){ if(g_nPlat<PLAT_MAX){ g_plat[g_nPlat][0]=a; g_plat[g_nPlat][1]=b; g_plat[g_nPlat][2]=c; g_nPlat++; } else printf("[data] %s: more than %d ledges, the rest dropped\n",path,PLAT_MAX); }
            else if(sscanf(ln,"orb %f %f",&a,&b)==2){ if(g_nOrb<ORB_MAX){ g_orb[g_nOrb][0]=a; g_orb[g_nOrb][1]=b; g_nOrb++; } else printf("[data] %s: more than %d orbs (GM.count is a bitmask), the rest dropped\n",path,ORB_MAX); }
            else if(sscanf(ln,"goal %f",&a)==1) g_platGoal=a;
            else printf("[data] %s: line not understood: %s",path,ln); }
        fclose(f); }
    if(!g_nPlat){ if(!f) printf("[data] %s MISSING -- the built-in course\n",path); else printf("[data] %s has no ledges -- the built-in course\n",path);
        for(int i=0;i<GMPLAT_N;i++){ g_plat[i][0]=GMPLAT[i][0]; g_plat[i][1]=GMPLAT[i][1]; g_plat[i][2]=GMPLAT[i][2]; } g_nPlat=GMPLAT_N;
        for(int i=0;i<GMORB_N;i++){ g_orb[i][0]=GMORB[i][0]; g_orb[i][1]=GMORB[i][1]; } g_nOrb=GMORB_N; g_platGoal=GMPLAT_GOALX; }
    printf("[data] course %s: %d ledges, %d orbs, goal at x %.1f\n",f?path:"(built-in)",g_nPlat,g_nOrb,g_platGoal); fflush(stdout); }
/* the narrative RPG's script: who is where, what they say at which stage, what advances it */
typedef struct { int npc,st,plus; char text[96]; } QLine;   /* st -1 = any stage; plus: st or later */
static struct { int n; float x[4],z[4]; char name[4][32]; } g_qNpc;
static QLine g_qSay[64]; static int g_nSay=0;
static struct { int npc,st,nw,score; } g_qGoto[32]; static int g_nGoto=0;
static struct { int st,nw; float x,z; char text[96]; } g_qMark[8]; static int g_nMark=0;
static QLine g_qHud[16]; static int g_nHud=0;
static char g_qStart[96]={0}; static int g_qLoaded=0;
static int qStage(const char*tok,int*st,int*plus){ *plus=0; if(!strcmp(tok,"*")){ *st=-1; return 1; }
    int n=(int)strlen(tok); if(n>1&&tok[n-1]=='+'){ *plus=1; } *st=atoi(tok); return (tok[0]>='0'&&tok[0]<='9'); }
static int qMatch(int st,int plus,int stage){ return st<0||(plus?stage>=st:stage==st); }
static void questLoad(void){
    const char*path=getenv("REVA_NRPG_QUEST"); if(!path||!path[0]) path="data/nrpg_quest.txt";
    g_qNpc.n=0; g_nSay=g_nGoto=g_nMark=g_nHud=0; g_qStart[0]=0; g_qLoaded=0;
    FILE*f=fopen(path,"r"); if(!f){ printf("[data] %s MISSING -- the built-in errand\n",path); return; }
    char ln[300], tok[32], tok2[32]; int k,a,b,c;
    while(fgets(ln,sizeof ln,f)){ size_t L=strlen(ln); while(L&&(ln[L-1]=='\n'||ln[L-1]=='\r')) ln[--L]=0;
        if(!ln[0]||ln[0]=='#') continue;
        float x,z; int nread=0;
        if(sscanf(ln,"npc %d %f %f %n",&k,&x,&z,&nread)==3&&k>=0&&k<4){ g_qNpc.x[k]=x; g_qNpc.z[k]=z; snprintf(g_qNpc.name[k],32,"%s",ln+nread); if(k+1>g_qNpc.n) g_qNpc.n=k+1; }
        else if(sscanf(ln,"say %d %31s %n",&k,tok,&nread)==2&&g_nSay<64){ QLine*q=&g_qSay[g_nSay]; if(!qStage(tok,&q->st,&q->plus)){ printf("[data] %s: bad stage '%s'\n",path,tok); continue; } q->npc=k; snprintf(q->text,96,"%s",ln+nread); g_nSay++; }
        else if(sscanf(ln,"goto %d %d %d %d",&k,&a,&b,&c)>=3&&g_nGoto<32){ int n9=sscanf(ln,"goto %d %d %d %d",&k,&a,&b,&c); g_qGoto[g_nGoto].npc=k; g_qGoto[g_nGoto].st=a; g_qGoto[g_nGoto].nw=b; g_qGoto[g_nGoto].score=(n9>=4)?c:0; g_nGoto++; }
        else if(sscanf(ln,"marker %d %f %f %d %n",&a,&x,&z,&b,&nread)==4&&g_nMark<8){ g_qMark[g_nMark].st=a; g_qMark[g_nMark].x=x; g_qMark[g_nMark].z=z; g_qMark[g_nMark].nw=b; snprintf(g_qMark[g_nMark].text,96,"%s",ln+nread); g_nMark++; }
        else if(sscanf(ln,"hud %31s %n",tok,&nread)==1&&g_nHud<16){ QLine*q=&g_qHud[g_nHud]; if(!qStage(tok,&q->st,&q->plus)){ printf("[data] %s: bad stage '%s'\n",path,tok); continue; } q->npc=-1; snprintf(q->text,96,"%s",ln+nread); g_nHud++; }
        else if(!strncmp(ln,"start ",6)) snprintf(g_qStart,96,"%s",ln+6);
        else printf("[data] %s: line not understood: %s\n",path,ln);
        (void)tok2; }
    fclose(f);
    g_qLoaded=(g_qNpc.n>0);
    printf("[data] quest %s: %d regulars, %d lines, %d advances, %d markers, %d hud lines%s\n",path,g_qNpc.n,g_nSay,g_nGoto,g_nMark,g_nHud,g_qLoaded?"":" -- no npc lines: the built-in errand"); fflush(stdout); }
static const char* qSayFor(int npc,int stage){ for(int i=0;i<g_nSay;i++) if(g_qSay[i].npc==npc&&qMatch(g_qSay[i].st,g_qSay[i].plus,stage)) return g_qSay[i].text; return NULL; }
static const char* qHudFor(int stage){ for(int i=0;i<g_nHud;i++) if(qMatch(g_qHud[i].st,g_qHud[i].plus,stage)) return g_qHud[i].text; return "..."; }
