    if(!strcmp(nm,"chest")) return ATT_CHEST;
    if(!strcmp(nm,"hip"))   return ATT_HIP;
    if(!strcmp(nm,"lhand")) return ATT_LHAND;
    if(!strcmp(nm,"deck"))  return ATT_DECK;
