    int att;
    if(H->where[0])   att=attOf(H->where);              /* the script said where: obey it */
    else if(which==0) att=ATT_HAND;                     /* the old default, unchanged */
    else              att=(a1==ATT_HAND)?ATT_LHAND:ATT_HAND;
