static float clipStride(Pack*P,int clip){
    /* Returns how far the CONTACT foot travels backwards, in club units per clip frame.
     * Average stride-per-cycle is the wrong quantity for a run: contact is only a third
     * of the cycle, so a clip matched on cycle average still slides while the foot is
     * down. What actually locks a foot is its backward speed WHILE PLANTED equalling the
     * body's forward speed, so that is what gets measured -- over the low-foot frames
     * only. Rate then follows: rate = speed / (fps * this). */
    if(!P||clip<0||(unsigned)clip>=P->nClips||P->footL<0||P->footR<0||P->nNodes>512) return 0.f;
    PClip*c=&P->clips[clip]; if(c->frames<4) return 0.f;
    static float T[512][3],Q[512][4],S[512][3]; static M4 W[512];
    unsigned N=c->frames; if(N>60) N=60;
    static float fx[61][2],fz[61][2],fy[61][2];
    for(unsigned k=0;k<N;k++){
        unsigned f=(unsigned)((float)k/(float)N*(float)c->frames)%c->frames;
        for(unsigned i=0;i<P->nNodes;i++){ memcpy(T[i],P->nodes[i].t,12);
            memcpy(Q[i],P->nodes[i].q,16); memcpy(S[i],P->nodes[i].s,12); }
        unsigned char*tr=P->pk+c->offTracks;
        for(unsigned t=0;t<c->nTracks;t++){ unsigned node=*(unsigned*)(tr+t*12),type=*(unsigned*)(tr+t*12+4),offD=*(unsigned*)(tr+t*12+8);
            if(node>=P->nNodes) continue;
            float*d=(float*)(P->pk+offD); int comp=type==0?4:3;
            if(type>=3) continue; else if(type==0) memcpy(Q[node],d+(size_t)f*comp,16);
            else if(type==1) memcpy(T[node],d+(size_t)f*comp,12);
            else memcpy(S[node],d+(size_t)f*comp,12); }
        for(unsigned i=0;i<P->nNodes;i++){ M4 loc; m4_trs(loc,T[i],Q[i],S[i]);
            if(P->nodes[i].parent<0) memcpy(W[i],loc,64); else m4_mul(W[i],W[P->nodes[i].parent],loc); }
        int fb[2]={P->footL,P->footR};
        for(int e=0;e<2;e++){ fx[k][e]=W[fb[e]][12]*P->scale;
                              fy[k][e]=W[fb[e]][13]*P->scale;
                              fz[k][e]=W[fb[e]][14]*P->scale; } }
    float lo=1e9f,hi=-1e9f;
    for(unsigned k=0;k<N;k++) for(int e=0;e<2;e++){ if(fy[k][e]<lo) lo=fy[k][e]; if(fy[k][e]>hi) hi=fy[k][e]; }
    float thr=lo+(hi-lo)*0.25f;      /* the lowest quarter of the foot's travel = weight-bearing */
    double sum=0.0; int n=0;
    for(unsigned k=1;k<N;k++) for(int e=0;e<2;e++){
        if(fy[k][e]>thr||fy[k-1][e]>thr) continue;
        float d9=hypotf(fx[k][e]-fx[k-1][e],fz[k][e]-fz[k-1][e]);
        if(d9>0.6f) continue;         /* a cycle wrap, not a step */
        sum+=d9; n++; }
    if(!n) return 0.f;
    float perSample=(float)(sum/n);
    /* IS THIS CYCLE LOCKABLE? In a real in-place gait the planted foot travels backwards
     * at a STEADY rate, so one playback rate can cancel it. If that speed swings wildly
     * through contact, no rate locks the foot and the clip is stylised, not locomotion.
     * Report the spread so the role audit can see it. */
    { double var=0.0; int m=0;
      for(unsigned k=1;k<N;k++) for(int e=0;e<2;e++){
          if(fy[k][e]>thr||fy[k-1][e]>thr) continue;
          float d9=hypotf(fx[k][e]-fx[k-1][e],fz[k][e]-fz[k-1][e]);
          if(d9>0.6f) continue;
          var+=(d9-perSample)*(d9-perSample); m++; }
      float cv=(m>1&&perSample>1e-5f)?(float)(sqrt(var/m)/perSample):0.f;
      if(getenv("REVA_GAITDBG"))
          printf("[gait] %s clip %d '%s': contact %.4fu/frame  spread CV %.2f  %s\n",
                 P->label,clip,packStr(P,c->name),perSample,cv,
                 cv>0.65f?"<- UNLOCKABLE: foot speed swings through contact":"steady"); }
    return perSample*((float)N/(float)c->frames);   /* -> per CLIP frame */ }
static float clipStrideCached(Pack*P,int clip){
    static struct { Pack*p; int c; float s; } cache[24]; static int cn=0;
    for(int i=0;i<cn;i++) if(cache[i].p==P&&cache[i].c==clip) return cache[i].s;
    float st=clipStride(P,clip);
    if(cn<24){ cache[cn].p=P; cache[cn].c=clip; cache[cn].s=st; cn++;
        if(getenv("REVA_GAITDBG")) printf("[gait] %s clip %d: contact-foot %.4fu/frame (%u frames @ %.0ffps)\n",
            P->label,clip,st,P->clips[clip].frames,P->clips[clip].fps); }
    return st; }
/* ================= FOOT-LOCK SERVO (S6c) ===========================================
 * gaitRate() derives a playback rate from a clip's AVERAGE contact-foot speed. Average
 * is a guess about a specific instant: a clip whose stride varies through the cycle, or
 * a rig whose measurement was slightly off, still slides. So close the loop.
 *
 * The condition for a planted foot is exact and local:
 *     d(foot_world)/dt = body_velocity + R * d(foot_local)/dphase * dphase/dt = 0
 * Both terms are observable every frame -- the body moved a known amount, and the clip
 * moved the foot a known amount in the body's frame. Any residual IS the slip, so feed
 * it back into the phase rate and the error is driven to zero continuously, whatever the
 * clip, rig or speed.
 *
 * MEASURED AND REJECTED (2026-08-26). It is worse. Compounding a per-frame correction
 * with no damping runs to a rail: Manny's certified walk went 0.15 -> 0.42 and his run
 * 0.20 -> 1.67, and reva's walk 0.32 -> 1.00. The regression suite caught it against the
 * known-good baseline within one run, which is the whole reason the baseline exists.
 * Kept behind REVA_SERVO=1 as a documented negative result: a loop that needs its gain
 * hand-tuned is NOT correct by construction, while the open-loop derivation in
 * gaitRate() -- solve the clip for its own contact speed -- is. Anyone reviving this
 * needs contact-phase gating, damping toward 1, and to beat the baseline before it
 * becomes the default. */
static char g_shotNow[512]={0};    /* live capture request: written by the lab control file */
static float g_servo=1.f;          /* live multiplier on the derived rate */
static float g_servoSlip=0.f;      /* |residual| this frame, for the lab HUD */
static float g_runMul=0.f;
static float runMul(void){ if(g_runMul<=0.f){ const char*e=getenv("REVA_RUNMUL");
        g_runMul=e?(float)atof(e):0.42f; } return g_runMul; }
static float gaitRate(Pack*P,int clip,float spd){
    if(getenv("REVA_NOAUTOGAIT")) return spd*gaitMul();
    if(clip<0||(unsigned)clip>=P->nClips) return spd*gaitMul();
    PClip*c=&P->clips[clip];
    /* MEASURED at bake time from the root-motion sibling. OPT-IN (REVA_GAITSIDECAR=1):
     * exact for a clip played on its OWN rig, but these are transferred onto other
     * bodies and stride scales with the target's leg length, so the raw authored number
     * regressed the certified baseline (manny run skate 0.20 -> 0.33). It needs a
     * source/target limb-length ratio before it can be the default; the sidecar and the
     * measurement are kept because the number itself is right. */
    static int useSide=-1; if(useSide<0) useSide=getenv("REVA_GAITSIDECAR")?1:0;
    if(useSide&&P->gaitUPS&&P->gaitUPS[clip]>0.05f){
        float r2=spd/P->gaitUPS[clip]*g_servo;
        if(r2<0.05f) r2=0.05f; if(r2>6.f) r2=6.f;
        return r2; }
    float fpf=clipStrideCached(P,clip);      /* club units the planted foot covers per frame */
    if(fpf<0.004f||c->fps<=0.f||!c->frames) return spd*gaitMul();   /* not a gait: keep the old law */
    float r=spd/(c->fps*fpf)*g_servo;   /* the loop closes here */
    if(r<0.05f) r=0.05f; if(r>6.f) r=6.f;
    return r; }
